package db

import (
	"context"
	"database/sql"
	"errors"
)

const restoreTransactionsMigration = "011_restore_transactions.sql"

// restoreTransactions removes the compensation generated by the retired
// standalone action. A replacement has its own create audit record and both
// sides of that correction must remain in the ledger.
func restoreTransactions(ctx context.Context, tx *sql.Tx, selection string) error {
	type restoration struct {
		household, transaction, original, reversal string
	}
	rows, err := tx.QueryContext(ctx, selection)
	if err != nil {
		return err
	}
	defer rows.Close()
	var items []restoration
	for rows.Next() {
		var item restoration
		if err := rows.Scan(&item.household, &item.transaction, &item.original, &item.reversal); err != nil {
			return err
		}
		items = append(items, item)
	}
	if err := rows.Err(); err != nil {
		return err
	}
	if err := rows.Close(); err != nil {
		return err
	}
	for _, item := range items {
		var statement string
		var compensation int64
		err := tx.QueryRowContext(ctx, `
			SELECT i.statement_id,i.amount_minor FROM credit_statement_items i
			JOIN credit_statements s ON s.id=i.statement_id
			WHERE s.household_id=? AND i.source_type='reversal' AND i.source_id=?`,
			item.household, item.reversal).Scan(&statement, &compensation)
		if err != nil && !errors.Is(err, sql.ErrNoRows) {
			return err
		}
		if err == nil {
			if _, err := tx.ExecContext(ctx, `UPDATE credit_statements
				SET system_due_minor=system_due_minor-? WHERE id=? AND household_id=?`,
				compensation, statement, item.household); err != nil {
				return err
			}
			if _, err := tx.ExecContext(ctx, `UPDATE schedule_due_items SET amount_minor=(
				SELECT system_due_minor-paid_minor FROM credit_statements WHERE id=? AND household_id=?)
				WHERE household_id=? AND source_type='credit_statement' AND source_id=? AND status='pending'`,
				statement, item.household, item.household, statement); err != nil {
				return err
			}
			if _, err := tx.ExecContext(ctx, `DELETE FROM credit_statement_items
				WHERE statement_id=? AND source_type='reversal' AND source_id=?`, statement, item.reversal); err != nil {
				return err
			}
		}
		for _, change := range []struct {
			query string
			id    string
		}{
			{`DELETE FROM journal_lines WHERE entry_id=? AND EXISTS (
				SELECT 1 FROM journal_entries e WHERE e.id=journal_lines.entry_id AND e.household_id=?)`, item.reversal},
			{`DELETE FROM journal_entries WHERE id=? AND household_id=?`, item.reversal},
			{`UPDATE journal_entries SET status='posted' WHERE id=? AND household_id=?`, item.original},
			{`UPDATE transactions SET status='posted' WHERE id=? AND household_id=?`, item.transaction},
		} {
			if _, err := tx.ExecContext(ctx, change.query, change.id, item.household); err != nil {
				return err
			}
		}
	}
	return nil
}
